c.cpp:
class Solution {
public:
    int averageValue(vector<int>& nums){
        long long s=0; int c=0;
        for(int x:nums) if(x%6==0){s+=x;c++;}
        return c?(int)(s/c):0;
    }
};

c.java:
class Solution {
    public int averageValue(int[] nums){
        long s=0; int c=0;
        for(int x:nums) if(x%6==0){s+=x;c++;}
        return c==0?0:(int)(s/c);
    }
}

